import json, os, sys
D = os.path.dirname(os.path.abspath(__file__))
PREFIX = "Flat vector cartoon sticker art for a cute 2D side-scrolling mobile game: thick uniform dark-purple outlines (#2b2233) around every shape, flat color fills with exactly one hard-edged cel-shade step, no gradients, no texture, warm sunset palette of coral, peach, cream, lavender and teal accents, clean bold graphic shapes readable at small size, strict side view orthographic elevation, transparent background, absolutely no text, no letters, no numbers, no digits, no logos, no brand trade dress."
TAIL = " One single isolated game obstacle prop, centered on the canvas with generous empty transparent margin, nothing else in the image: no ground line, no floor, no cast shadow, no drop shadow, no background scenery, no sky."
P = {
 "filebox": ("1:1", "Subject: a stack of exactly two brown cardboard file storage boxes, one sitting squarely on top of the other, drawn in pure flat side elevation with NO perspective: only the flat front face of each box is visible, no top face, no side face, no depth. Each box is a WIDE landscape rectangle (about 8 wide by 4.5 tall) with a slightly overhanging lid band at its top, a strip of cream packing tape running vertically over the lid band, and a small oval hand-hold cutout. Plain kraft-brown cardboard, no labels, no writing. The whole two-box stack is nearly square, only slightly taller than wide (about 8 wide by 9 tall)."),
 "chair": ("1:1", "Subject: a compact rolling office chair in pure flat side profile facing right, no perspective: a thick teal padded seat cushion, a very LOW short teal backrest at the left end that rises only a little above the seat, no armrests, a single short central chrome gas-lift column, and a wide star base seen from the side so that exactly three small dark caster wheels are visible along the bottom, spread wide apart. The chair is squat and wide: overall silhouette almost square (about 9 wide by 10 tall), the wheel base nearly as wide as the seat."),
 "scaffold": ("3:4", "Subject: one wide section of construction scaffolding in flat front elevation: a WIDE rectangular frame of grey metal pipes with three vertical uprights (left, middle, right), horizontal ledgers at the top and middle, and one diagonal brace, covered by a draped green mesh safety net with a fine diamond net pattern, and along the bottom edge a horizontal board painted with diagonal yellow and black warning stripes. The frame is wide and stocky: overall silhouette exactly 3 wide by 4 tall (width three quarters of height), pipe ends only slightly protruding."),
 "shopbar": ("3:4", "Subject: a low-hanging street shop sign obstacle, composed from top to bottom: at the very top, the front edge of a fabric awning with red and cream vertical stripes and a scalloped lower edge spanning the full width (about one fifth of the total height); directly under it a dark metal bracket bar; from the bracket two LONG chains (about one quarter of the total height) hold a horizontal rectangular signboard that fills the lower half. The signboard is a blank warm orange board with a cream inner border and only one simple centered icon of a skewer of three round brown-red meatballs on a stick, no writing at all. The overall silhouette is clearly taller than wide: width about four fifths of height (7 wide by 8.6 tall)."),
 "step": ("16:9", "Subject: a wide raised stone curb block / step you can stand on, a chunky thick horizontal rectangular slab whose height is exactly one quarter of its width (4 wide by 1 tall), perfectly flat level top surface, slightly rounded corners, warm light grey-beige stone with a cream highlight strip along the top edge, one darker cel-shade band along the bottom, and two thin vertical seams dividing it into three blocks. Pure front elevation, no perspective, no top face visible."),
 "manhole": ("16:9", "Subject: an open street manhole seen from a low side angle, drawn as two flat ellipses side by side on the same baseline: on the left, the dark purple-black hole as an ellipse about three times wider than tall with a thick grey concrete rim ring; just to its right, almost touching it, the round heavy dark-grey iron manhole cover lying flat on the ground, shown as a thick disc (ellipse top face about three times wider than tall plus a visible vertical edge band) with a simple grid tread pattern. The combined shape of both objects is about five times wider than tall. Only these two objects, no surrounding pavement."),
 "bun": ("4:3", "Subject: a single white Chinese steamed bun (baozi) seen from the side: a TALL plump rounded dome with a flat bottom, its height about five sixths of its width (6 wide by 5 tall), with twisted pleats gathered into a small swirl knot on top, cream-white with a soft peach cel-shade step. No plate, no steamer basket, no steam."),
}
for k in (sys.argv[1:] or list(P)):
    ar, body = P[k]
    req = {"command": "image.generate", "args": [{"prompt": PREFIX + " " + body + TAIL, "model": "gpt-image-2.5-flare", "quality": "medium", "aspectRatio": ar, "imageSize": "2K", "background": "transparent", "name": k + "_v2"}]}
    with open(os.path.join(D, k + "_v2.json"), "w", encoding="utf-8") as f:
        json.dump(req, f, ensure_ascii=False)
print("ok")
